<?php

/* @autogenerated */
declare(strict_types=1);

namespace Tests\integration\Features\OAuth;

use Nimbly\Capsule\Response;
use Slim\Factory\AppFactory;
use Civi\Lughauth\Bootstrap\Plugin\OAuthPlugin;
use Civi\Lughauth\Features\OAuth\Oidc\Domain\OidcCapabilities;
use Civi\Lughauth\Features\OAuth\Oidc\Infrastructure\Driven\MtlsDiscoveryContributor;
use Civi\Lughauth\Features\OAuth\Oidc\Infrastructure\Driver\Rest\OpenIdConfigurationController;
use Civi\Lughauth\Features\OAuth\TokenSecurity\Infrastructure\Driver\Rest\JwksController;

class DiscoveryTest extends OidcIntegrationTestCase
{
    private OpenIdConfigurationController $controller;

    protected function setUp(): void
    {
        parent::setUp();
        $this->controller = $this->container->get(OpenIdConfigurationController::class);
    }

    public function testJwksIsIsolatedPerTenant(): void
    {
        $this->tokenStore->generateKey('tenant2');

        $own = $this->jwksKids(self::TENANT);
        $other = $this->jwksKids('tenant2');

        $this->assertContains($this->tokenStore->currentKey(self::TENANT)?->kid, $own);
        $this->assertContains($this->tokenStore->currentKey('tenant2')?->kid, $other);
        $this->assertSame([], array_values(array_intersect($own, $other)));
    }

    public function testRotationPublishesFutureKeysAndInvalidatesOnlyItsTenantJwks(): void
    {
        $this->tokenStore->generateKey('tenant2');
        $before = $this->jwksKids(self::TENANT);
        $otherBefore = $this->jwksKids('tenant2');

        $created = $this->keyRotation()->rotate(self::TENANT);

        $this->assertGreaterThan(0, $created);
        $this->assertCount(count($before) + $created, $this->jwksKids(self::TENANT), 'Future keys are published before they sign');
        $this->tokenStore->generateKey('tenant2');
        $this->assertSame($otherBefore, $this->jwksKids('tenant2'), 'Another tenant keeps its cached JWKS');
    }

    /** @return list<string> */
    private function jwksKids(string $tenant): array
    {
        $controller = $this->container->get(JwksController::class);
        $response = $controller->get($this->makeRequest('GET', "/oauth/openid/$tenant/jwks"), new Response(200), ['tenant' => $tenant]);
        return array_column($this->decodeJson($response)['keys'] ?? [], 'kid');
    }

    private function discover(string $tenant = self::TENANT, ?OpenIdConfigurationController $controller = null): array
    {
        $request = $this->makeRequest('GET', "/oauth/openid/$tenant/.well-known/openid-configuration");
        $response = ($controller ?? $this->controller)->get($request, new Response(200), ['tenant' => $tenant]);
        $this->assertSame(200, $response->getStatusCode());
        $this->assertStringContainsString('application/json', $response->getHeaderLine('Content-Type'));
        return $this->decodeJson($response);
    }

    public function testDiscoveryReturns200WithJsonContentType(): void
    {
        $request = $this->makeRequest('GET', '/oauth/openid/' . self::TENANT . '/.well-known/openid-configuration');
        $response = $this->controller->get($request, new Response(200), ['tenant' => self::TENANT]);

        $this->assertSame(200, $response->getStatusCode());
        $this->assertStringContainsString('application/json', $response->getHeaderLine('Content-Type'));
    }

    public function testDiscoveryContainsRequiredRfc8414Fields(): void
    {
        $doc = $this->discover();

        $required = [
            'issuer',
            'authorization_endpoint',
            'token_endpoint',
            'jwks_uri',
            'response_types_supported',
            'subject_types_supported',
        ];
        foreach ($required as $field) {
            $this->assertArrayHasKey($field, $doc, "Discovery document missing required field: $field");
        }
    }

    public function testIssuerMatchesTenantPath(): void
    {
        $doc = $this->discover();

        $this->assertStringContainsString(self::TENANT, $doc['issuer']);
    }

    public function testIssuerCannotBeChangedByRequestHost(): void
    {
        $expected = $this->discover();
        $_SERVER['HTTP_HOST'] = 'attacker.example';
        $_SERVER['HTTPS'] = 'on';

        $actual = $this->discover();
        $this->assertSame($expected['issuer'], $actual['issuer']);
        $this->assertSame($expected['token_endpoint'], $actual['token_endpoint']);
        $this->assertSame('http://localhost/oauth/openid/tenant1', $actual['issuer']);
    }

    public function testEndpointsAreAbsoluteUrls(): void
    {
        $doc = $this->discover();

        $endpoints = [
            'authorization_endpoint',
            'token_endpoint',
            'introspection_endpoint',
            'userinfo_endpoint',
            'end_session_endpoint',
            'jwks_uri',
            'revocation_endpoint',
            'device_authorization_endpoint',
            'pushed_authorization_request_endpoint',
        ];
        foreach ($endpoints as $field) {
            $this->assertStringStartsWith('http', $doc[$field], "$field must be an absolute URL");
        }
    }

    public function testGrantTypesSupportedContainsStandardGrants(): void
    {
        $doc = $this->discover();

        $this->assertContains('authorization_code', $doc['grant_types_supported']);
        $this->assertContains('client_credentials', $doc['grant_types_supported']);
        $this->assertContains('refresh_token', $doc['grant_types_supported']);
        $this->assertContains('urn:ietf:params:oauth:grant-type:device_code', $doc['grant_types_supported']);
    }

    public function testCodeChallengeMethodsIncludeS256(): void
    {
        $doc = $this->discover();

        $this->assertContains('S256', $doc['code_challenge_methods_supported']);
    }

    public function testBackchannelLogoutSupportedIsTrue(): void
    {
        $doc = $this->discover();

        $this->assertTrue($doc['backchannel_logout_supported']);
        $this->assertTrue($doc['backchannel_logout_session_supported']);
    }

    public function testMtlsEndpointAliasesAreAbsentWithoutTrustedTermination(): void
    {
        $doc = $this->discover();

        $this->assertArrayNotHasKey('mtls_endpoint_aliases', $doc);
    }

    public function testMtlsEndpointAliasesArePresentWithTrustedTermination(): void
    {
        $doc = $this->discover(controller: $this->controllerWithMtls());

        $this->assertSame('https://mtls.example/openid/tenant1/token', $doc['mtls_endpoint_aliases']['token_endpoint']);
    }

    public function testContributorCannotOverrideBaseFields(): void
    {
        $controller = new OpenIdConfigurationController($this->context, $this->parPolicy, [new class () implements \Civi\Lughauth\Features\OAuth\Oidc\Domain\Gateway\DiscoveryContributorGateway {
            public function contribute(\Civi\Lughauth\Features\OAuth\Oidc\Domain\OpenIdConfiguration $base, string $tenant): array
            {
                return ['issuer' => 'https://attacker.example'];
            }
        }]);

        $this->expectException(\LogicException::class);
        $this->discover(controller: $controller);
    }

    public function testEveryAnnouncedEndpointIsRegisteredInOAuthPlugin(): void
    {
        $doc = $this->discover(controller: $this->controllerWithMtls());
        $routes = $this->oauthPluginRoutes();

        $endpoints = [];
        foreach ([$doc, $doc['mtls_endpoint_aliases']] as $metadata) {
            foreach ($metadata as $field => $value) {
                if (is_string($value) && (str_ends_with($field, '_endpoint') || str_ends_with($field, '_uri') || str_ends_with($field, '_iframe'))) {
                    $endpoints[] = [$field, $value];
                }
            }
        }
        $this->assertNotEmpty($endpoints);
        foreach ($endpoints as [$field, $url]) {
            $urlPath = parse_url($url, PHP_URL_PATH);
            $this->assertIsString($urlPath, "$field must have a URL path");
            $path = (string) preg_replace('#^/(?:oauth/)?openid/' . self::TENANT . '#', '/oauth/openid/{tenant}', $urlPath);
            $this->assertContains($path, $routes, "$field ($url) is announced but not routed in OAuthPlugin");
        }
    }

    public function testEveryActiveFlagIsBackedByACapability(): void
    {
        $doc = $this->discover();
        $caps = OidcCapabilities::implemented();

        $this->assertSame($caps->requirePushedAuthorizationRequests, $doc['require_pushed_authorization_requests']);
        $this->assertSame($caps->claimsParameter, $doc['claims_parameter_supported']);
        $this->assertSame($caps->requestParameter, $doc['request_parameter_supported']);
        $this->assertSame($caps->authorizationResponseIssParameter, $doc['authorization_response_iss_parameter_supported']);
        $this->assertSame($caps->backchannelLogout, $doc['backchannel_logout_supported']);
        $this->assertSame($caps->frontchannelLogout, $doc['frontchannel_logout_supported']);
        $this->assertSame($caps->grantTypes, $doc['grant_types_supported']);
        $this->assertSame($caps->responseTypes, $doc['response_types_supported']);
        $this->assertSame($caps->responseModes, $doc['response_modes_supported']);
        $this->assertSame($caps->codeChallengeMethods, $doc['code_challenge_methods_supported']);
        $this->assertSame($caps->subjectTypes, $doc['subject_types_supported']);
        $this->assertFalse($doc['tls_client_certificate_bound_access_tokens']);
        $this->assertFalse($doc['request_uri_parameter_supported']);
        $this->assertSame($caps->uiLocales, $doc['ui_locales_supported']);
    }

    /** EP-11: every endpoint that authenticates clients through ClientAuthenticator accepts private_key_jwt. */
    public function testClientAuthenticationMethodsIncludePrivateKeyJwtWithItsAlgorithms(): void
    {
        $doc = $this->discover();

        foreach (['token_endpoint', 'introspection_endpoint', 'revocation_endpoint'] as $endpoint) {
            $this->assertContains('private_key_jwt', $doc["{$endpoint}_auth_methods_supported"], $endpoint);
            $this->assertNotContains('client_secret_jwt', $doc["{$endpoint}_auth_methods_supported"], $endpoint);
            $this->assertSame(['RS256', 'ES256', 'PS256'], $doc["{$endpoint}_auth_signing_alg_values_supported"], $endpoint);
        }
        $this->assertNotContains('urn:ietf:params:oauth:grant-type:jwt-bearer', $doc['grant_types_supported']);
    }

    public function testEveryAnnouncedUiLocaleHasALoginCatalogue(): void
    {
        $translations = dirname(__DIR__, 4) . '/src/Features/OAuth/Authentication/Infrastructure/Driver/Translations';
        foreach ($this->discover()['ui_locales_supported'] as $locale) {
            // The base catalogue is English (MessageProvider); every other language has its own file.
            $file = $locale === 'en' ? 'forms.yaml' : "forms.{$locale}.yaml";
            $this->assertFileExists("{$translations}/{$file}", "ui_locales_supported announces {$locale} without a catalogue");
        }
    }

    private function controllerWithMtls(): OpenIdConfigurationController
    {
        return new OpenIdConfigurationController($this->context, $this->parPolicy, [new MtlsDiscoveryContributor('https://mtls.example')]);
    }

    /** @return string[] */
    private function oauthPluginRoutes(): array
    {
        $app = AppFactory::create();
        (new OAuthPlugin())->registerRoutes($app);
        return array_map(fn ($route) => $route->getPattern(), $app->getRouteCollector()->getRoutes());
    }

    public function testDifferentTenantsReturnDifferentIssuers(): void
    {
        $doc1 = $this->discover('tenant-a');
        $doc2 = $this->discover('tenant-b');

        $this->assertNotSame($doc1['issuer'], $doc2['issuer']);
        $this->assertStringContainsString('tenant-a', $doc1['issuer']);
        $this->assertStringContainsString('tenant-b', $doc2['issuer']);
    }

    public function testRequirePushedAuthorizationRequestsIsFalse(): void
    {
        $doc = $this->discover();

        $this->assertFalse($doc['require_pushed_authorization_requests']);
    }

    public function testRequirePushedAuthorizationRequestsFollowsTheTenantConfiguration(): void
    {
        $this->parPolicy->requirePar('tenant2');

        $this->assertTrue($this->discover('tenant2')['require_pushed_authorization_requests']);
        $this->assertFalse($this->discover()['require_pushed_authorization_requests']);
    }
}
